import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"CFI 直觉","description":"","frontmatter":{"title":"CFI 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cfi.md","filePath":"cs/cfi.md","lastUpdated":1789023840000}'),E={name:"cs/cfi.md"};function h(_,a,f,A,u,m){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="cfi-直觉" tabindex="-1">CFI 直觉 <a class="header-anchor" href="#cfi-直觉" aria-label="Permalink to &quot;CFI 直觉&quot;">​</a></h1><div class="epigraph"><p>即使能改代码指针，也只允许跳到编译器承认的合法目标集；控制流完整性把「任意地址」收成图上的边。</p><footer>—— Abadi, Budiu, Erlingsson and Ligatti, Control-Flow Integrity, 2005；对照 NX/ASLR</footer></div><p><a href="/cs/aslr-nx">上一课</a>用不可执行与随机布局提高利用代价。本课不描述如何绕过它们。缺口是：数据仍可写时，函数指针与返回地址仍可能被改到「碰巧可执行」的已有代码。CFI：运行时检查间接跳转目标属于该点的允许集。沙箱下一课是进程级隔离。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NX 禁止数据当代码；ASLR 隐藏地址。二者都不限制「跳到已存在的 gadget 式入口」。CFI 的缺口是<strong>把控制流图当成策略</strong>：间接调用只能进允许的函数入口，返回只能回合法调用点（粗或细粒度）。本课只讲机制与残差（粒度粗则允许集大），不给构造非法流的步骤。</p><p><span class="marginnote">硬件 CET 一类是实现轴。完整性仍依赖内存未被任意写到标签本身。CFI 不是类型安全。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器插标签或用类型粗分目标。运行时比较。与影子栈配合守返回。失败则中止，服务 CIA 的 I（控制流）。本课不选某家编译器开关当标准。</p>',8)),(e(),n(p,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IND%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%E8%BD%AC%22%5D%20--%3E%20SET%5B%22%E5%85%81%E8%AE%B8%E7%9B%AE%E6%A0%87%E9%9B%86%E5%90%88%22%5D%0A%20%20SET%20--%3E%20OK%5B%22%E5%9C%A8%E9%9B%86%E5%90%88%E5%86%85%E5%88%99%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20SET%20--%3E%20STOP%5B%22%E5%90%A6%E5%88%99%E4%B8%AD%E6%AD%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CFI 把<a href="/cs/buffer-overflow">缓冲区溢出</a> 之后「能改指针」的后果从任意控制收成图上的边。它不修越界本身。后课隔离假定即使控制流被弄歪，也还有进程边界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有代码复用防御写成年表。不可信代码的进程/内核边界，下一课隔离与沙箱。</p><p>后课默认：间接控制流可被政策约束。不信任的程序还要关进盒子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CFI 限制间接跳转的合法目标。</li><li>补 NX/ASLR 不管的「跳到已有代码」。</li><li>沙箱下一课。</li><li>出处：Abadi et al., 2005；对照 Anderson。</li></ul>',7))])}const T=o(E,[["render",h]]);export{C as __pageData,T as default};
